lisaBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "lisaBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "spatialfamily",
                name = "lisa",
                version = c(1,0,0),
                options = options,
                results = lisaResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Local Spatial Autocorrelation
#'
#' 
#' @param data .
#' @param var .
#' @param idVar .
#' @param xVar .
#' @param yVar .
#' @param wSource .
#' @param wFile .
#' @param wIdField .
#' @param wMethod .
#' @param wK .
#' @param wDist .
#' @param wPower .
#' @param wCutoff .
#' @param wOrder .
#' @param wCumul .
#' @param wSymm .
#' @param wLonLat .
#' @param wStyle .
#' @param showGuide .
#' @param showHelp .
#' @param stat .
#' @param nperm .
#' @param seed .
#' @param alpha .
#' @param adjust .
#' @param showUnits .
#' @param map .
#' @param scatter .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$units} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$clusterMap} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$scatterPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$saveCluster} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveStat} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveP} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$counts$asDF}
#'
#' \code{as.data.frame(results$counts)}
#'
#' @export
lisa <- function(
    data,
    var,
    idVar,
    xVar,
    yVar,
    wSource = "coords",
    wFile = "",
    wIdField = "",
    wMethod = "auto",
    wK = 5,
    wDist = 0,
    wPower = 1,
    wCutoff = 0,
    wOrder = 1,
    wCumul = FALSE,
    wSymm = FALSE,
    wLonLat = FALSE,
    wStyle = "W",
    showGuide = FALSE,
    showHelp = FALSE,
    stat = "localmoran",
    nperm = 999,
    seed = 1,
    alpha = 0.05,
    adjust = "none",
    showUnits = FALSE,
    map = TRUE,
    scatter = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("lisa requires jmvcore to be installed (restart may be required)")

    if ( ! missing(var)) var <- jmvcore::resolveQuo(jmvcore::enquo(var))
    if ( ! missing(idVar)) idVar <- jmvcore::resolveQuo(jmvcore::enquo(idVar))
    if ( ! missing(xVar)) xVar <- jmvcore::resolveQuo(jmvcore::enquo(xVar))
    if ( ! missing(yVar)) yVar <- jmvcore::resolveQuo(jmvcore::enquo(yVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(var), var, NULL),
            `if`( ! missing(idVar), idVar, NULL),
            `if`( ! missing(xVar), xVar, NULL),
            `if`( ! missing(yVar), yVar, NULL))


    options <- lisaOptions$new(
        var = var,
        idVar = idVar,
        xVar = xVar,
        yVar = yVar,
        wSource = wSource,
        wFile = wFile,
        wIdField = wIdField,
        wMethod = wMethod,
        wK = wK,
        wDist = wDist,
        wPower = wPower,
        wCutoff = wCutoff,
        wOrder = wOrder,
        wCumul = wCumul,
        wSymm = wSymm,
        wLonLat = wLonLat,
        wStyle = wStyle,
        showGuide = showGuide,
        showHelp = showHelp,
        stat = stat,
        nperm = nperm,
        seed = seed,
        alpha = alpha,
        adjust = adjust,
        showUnits = showUnits,
        map = map,
        scatter = scatter)

    analysis <- lisaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

